choose.when:
and ( (q.scope_type = 'LABORATORY' and exists ( select 1 from lab_laboratory scoped_laboratory where cast(scoped_laboratory.id as char) = q.scope_id and scoped_laboratory.del_flag = '0' and scoped_laboratory.id in
#{scopeLaboratoryId}
)) or q.scope_type = 'DEVICE_CATEGORY' )

mapper.select:
select 
from lab_qualification q
where q.del_flag = '0'


    and q.user_id = #{userId}


    and q.scope_type = #{scopeType}

select count(1)
from lab_qualification q
inner join lab_device d on d.id = #{deviceId}
                       and d.del_flag = '0'
where q.user_id = #{userId}
  and q.del_flag = '0'
  and q.valid_from <= #{at}
  and #{at} < q.valid_until
  and q.revoked_at is null
  and (
      (q.scope_type = 'LABORATORY' and q.scope_id = cast(d.laboratory_id as char))
      or (q.scope_type = 'DEVICE_CATEGORY' and q.scope_id = d.category_code)
  )
